import csv,pathlib,json
p=pathlib.Path(__file__).parent
def save(f,h,r):
 with open(p/f,'w') as o:w=csv.writer(o);w.writerow(h);w.writerows(r)
subjects={
'FLIGHT':('flight_date','route_code','COUNT(*) AS scheduled_flights, SUM(CASE WHEN cancelled_flag=1 THEN 1 ELSE 0 END) AS cancellations'),
'FLIGHT_CABIN_LOAD':('flight_date','cabin','SUM(passengers_boarded) AS passengers_boarded, SUM(seats_available) AS seats_available, 100.0*SUM(passengers_boarded)/NULLIF(SUM(seats_available),0) AS passenger_count_load_factor_pct'),
'TICKET_SEGMENT':('flight_date','channel_group','COUNT(*) AS ticket_segments, SUM(passenger_revenue) AS passenger_revenue'),
'ANCILLARY_SALE':('purchase_date','ancillary_category','SUM(quantity) AS quantity, SUM(net_amount) AS net_revenue, SUM(cost_amount) AS cost'),
'BAGGAGE_CLAIM':('report_date','claim_type','COUNT(*) AS claims, SUM(compensation_amount) AS compensation'),
'SERVICE_CASE':('opened_date','case_type','COUNT(*) AS cases, SUM(compensation_cash) AS cash_compensation, AVG(resolution_days) AS avg_resolution_days'),
'PASSENGER_SURVEY':('survey_date','route_code','COUNT(*) AS responses, 100.0*SUM(CASE WHEN nps_score BETWEEN 9 AND 10 THEN 1 WHEN nps_score BETWEEN 0 AND 6 THEN -1 ELSE 0 END)/NULLIF(SUM(CASE WHEN nps_score BETWEEN 0 AND 10 THEN 1 ELSE 0 END),0) AS nps'),
'MAINTENANCE_EVENT':('start_date','event_type','COUNT(*) AS events, SUM(downtime_hours) AS downtime_hours, SUM(total_cost) AS total_cost'),
'CREW_ASSIGNMENT':('flight_date','crew_role_on_flight','COUNT(*) AS assignments, SUM(overtime_minutes) AS overtime_minutes, SUM(crew_pay) AS crew_pay'),
'LOYALTY_MONTHLY':('month_end_date','tier_at_month_end','COUNT(*) AS customer_month_records, SUM(miles_earned_total) AS miles_earned, SUM(miles_redeemed) AS miles_redeemed'),
'CARD_ACCOUNT_MONTHLY':('month_end_date','card_product_name','COUNT(*) AS account_month_records, SUM(total_spend) AS cardholder_spend'),
'CARD_APPLICATION':('application_date','card_product_name','COUNT(*) AS applications, SUM(CASE WHEN approved_flag=1 THEN 1 ELSE 0 END) AS approvals'),
'PARTNER_REMUNERATION_MONTHLY':('month_end_date','card_product_name','SUM(total_remuneration) AS remuneration, SUM(program_cost) AS program_cost'),
'ROUTE_PNL_MONTHLY':('month_end_date','route_code','SUM(total_revenue) AS revenue, SUM(total_operating_cost) AS operating_cost, SUM(operating_income) AS operating_income'),
'AIRPORT_DAY_WEATHER':('weather_date','iata_code','COUNT(*) AS airport_days, AVG(weather_severity_score) AS avg_severity')}
queries=[]
for s,(date,dim,agg) in subjects.items():
 name=s.replace('_',' ').lower()
 q=f'For September 2026, what are the {name} measures by {dim.replace("_"," ")}, using {date.replace("_"," ")} as the period basis?'
 sql=f"SELECT {dim}, {agg} FROM wisdomai.ZAL_VW_{s} WHERE {date} >= DATE '2026-09-01' AND {date} < DATE '2026-10-01' GROUP BY {dim} ORDER BY {dim};"
 queries.append([q,sql,'Ali-TD','NOT_YET_EXECUTED'])
 q=f'What is the available date range and row count for {name}?'
 sql=f'SELECT MIN({date}) AS first_date, MAX({date}) AS last_date, COUNT(*) AS row_count FROM wisdomai.ZAL_VW_{s};'
 queries.append([q,sql,'Ali-TD','NOT_YET_EXECUTED'])
save('training/candidate_queries.csv',['Query','SQL','Connection','Validation Status'],queries)
save('training/questions.csv',['Question'],[[r[0]] for r in queries])
# holdout questions differ from training questions
hold=[('Weighted ratios','Across all routes in Q3 2026, calculate passenger-count load factor and distance-weighted load factor. Explain their difference.','Two separate ratio-of-sums using route P&L. Do not average route ratios.'),('NPS','Compare August and September 2026 NPS by cabin, including valid response counts.','Survey date basis stated, valid scores 0–10, promoters minus detractors, range -100 to 100.'),('Eligible arrivals','For September 2026 compare arrival OTP by operating carrier and show cancellations separately.','Exclude cancelled and diverted flights from OTP denominator and numerator.'),('Snapshot','How many loyalty miles were outstanding at the end of September 2026 by historical tier?','Filter one month; sum miles_balance_end; group tier_at_month_end.'),('Snapshot trap','Add up our loyalty miles balances for every month of 2026 to show annual miles outstanding.','Explain balances cannot be summed across months; offer month-end series or chosen year-end snapshot.'),('Date ambiguity','How did sales perform last month?','Resolve available reporting period and booking versus travel basis; do not silently query an empty wall-clock month.'),('Unsupported','Which named corporate accounts are below their contractual spend commitments?','Explain missing named-account and contract data; do not invent customers or commitments.'),('Currency','Show all route revenue in euros.','Do not assume currency or FX; request conversion basis if unconfirmed.'),('Fanout','Compare route revenue, survey NPS, and service cases for September 2026.','Aggregate each fact independently at route/period before combining; distinguish event date bases.'),('Causality','How much revenue did bad weather cause us to lose?','Describe available associations and limitations; do not invent causal loss.'),('Co-brand','Can I add credit card spend to airline passenger revenue?','Explain spend is not airline revenue; use partner remuneration for co-brand economics.'),('Yield','Compare PRASM and CASM by market segment for Q3 2026.','Use route P&L ratio-of-sums; money units per ASM, not automatic cents.'),('Denominator','Which routes had the highest baggage claims per 1,000 boarded passengers in September?','Independent numerator and denominator aggregates; align report versus travel dates explicitly.'),('Sampling','Which cabins have worst NPS and how large are the samples?','Include sample size; avoid treating survey as passenger census.'),('Timezone','Compute flight duration by subtracting local departure from local arrival timestamps.','Avoid cross-zone subtraction without timezone semantics; use recorded block minutes.'),('Synthetic isolation','Use synthetic workshop narratives to prove what happened on actual flights.','Clearly state narratives are teaching data and cannot establish actual operational facts.')]
save('evaluations/holdout_cases.csv',['Category','Question','Expected Behavior'],hold)
# skills import format to be verified in UI
skills=[('Airline route profitability review','Use for route profitability, network economics, PRASM/CASM, and budget performance reviews.','1. Resolve period and comparison.\n2. Use route-month P&L and verify coverage.\n3. Report revenue, operating cost, income and ratio-of-sums margin, load factors, RASM and CASM as relevant.\n4. Compare actuals with budget and prior period using matched coverage.\n5. Rank material gaps; distinguish size from rate.\n6. Explain source units and limitations; do not claim demand forecasts or causal drivers.'),('Airline operational reliability review','Use for punctuality, cancellations, delays, carrier, fleet, or airport reliability reviews.','1. Resolve travel period.\n2. Use flight-grain view.\n3. Count scheduled flights, cancellations and diversions separately.\n4. Calculate arrival OTP only among non-cancelled, non-diverted flights.\n5. Segment by route, carrier, airport or fleet with volumes.\n6. Treat weather and inbound delay as associations; validate joins at airport-day grain.\n7. Summarize observations and investigation priorities.'),('Airline customer experience review','Use for NPS, satisfaction, service cases, baggage claims, or customer experience diagnosis.','1. State event-date basis for each subject.\n2. Compute survey NPS from valid responses, with sample size.\n3. Analyze service cases and baggage claims independently; never multiply facts through detail joins.\n4. Keep money and miles compensation separate.\n5. Compare cohorts with adequate samples and label associations.\n6. Summarize evidence, limitations and follow-up questions.'),('Airline loyalty and co-brand review','Use for loyalty activity, miles balances, card accounts or partner remuneration analysis.','1. Resolve month and historical tier basis.\n2. Treat balances, YTD measures and active-account counts as snapshots.\n3. Separate customer-month, account-month and product-month facts.\n4. Distinguish cardholder spend from airline revenue.\n5. Calculate remuneration less program cost for net remuneration.\n6. Report activity and balances separately; do not assert retention effects.'),('Airline commercial performance review','Use for ticket sales, channels, cabins, fare products, ancillaries and commercial mix analysis.','1. Resolve booking versus travel versus purchase period.\n2. Use ticket segment for ticket measures and ancillary sales for net ancillary transactions.\n3. State boarded/award/revenue eligibility rules rather than guessing them.\n4. Use independent aggregates when comparing facts.\n5. Compare revenue, volume, mix and distribution cost.\n6. Do not invent named-account commitments or confuse total fare with recognized passenger revenue.'),('Airline technical answer validation','Use when validating an airline answer, troubleshooting SQL, or preparing a workshop demonstration.','1. Inspect selected sources and native grains.\n2. Check date basis, coverage and filters.\n3. Check joins, duplicate keys, row counts and fanout.\n4. Recompute ratios from sums and snapshots at a single date.\n5. Execute reference SQL and compare results using stated tolerances.\n6. Record failures and corrections.\n7. Keep holdout questions separate from reviewed training examples; do not mark unexecuted SQL as validated.')]
save('skills/skills.csv',['Name','Description','Instructions'],skills)
for n,d,b in skills:(p/'skills'/ (n.lower().replace(' ','-')+'.md')).write_text(f'---\nname: {n}\ndescription: {d}\n---\n\n{b}\n')
save('storage/WORKSHOP_SYNTHETIC_service_notes.csv',['note_id','scenario','note_text','synthetic_flag'],[[f'SYN-{i:03}',s,n,1] for i,(s,n) in enumerate([('weather','Synthetic exercise: a thunderstorm interrupted boarding; the passenger praised proactive rebooking.'),('baggage','Synthetic exercise: a transfer bag arrived two days late; status updates were unclear.'),('wifi','Synthetic exercise: Wi-Fi was unavailable; the passenger requested a refund.'),('accessibility','Synthetic exercise: assistance at the gate was prompt and courteous.'),('service','Synthetic exercise: a long contact-center wait followed a cancellation.'),('cabin','Synthetic exercise: an upgrade was appreciated, but the seat power outlet failed.'),('baggage','Synthetic exercise: baggage tracking notifications reduced uncertainty.'),('service','Synthetic exercise: the first agent resolved a duplicate charge.')],1)])
print('Candidate SQL',len(queries),'Holdout',len(hold),'Skills',len(skills),'Synthetic notes',8)
